P = practice(); lab2i = {l:i for i,l in enumerate(LABELS)}
y = np.array([lab2i[p['label']] for p in P])[:1024]
M = {l: np.load(f'pass_2/mean_hidden_L{l}.npy').astype(np.float64) for l in [6,8,11]}
Cl = {l: np.load(f'pass_2/cls_hidden_L{l}.npy').astype(np.float64) for l in [9,11,12]}
LN = lambda X: (X-X.mean(1,keepdims=True))/X.std(1,keepdims=True)
def cv_acc(X, y, lam, reps=4):
    n,d = X.shape; accs=[]
    for r in range(reps):
        perm = np.random.default_rng(r).permutation(n); folds = np.array_split(perm, 5)
        c=0
        for f in folds:
            tr = np.setdiff1d(np.arange(n), f)
            mu = X[tr].mean(0); sd = X[tr].std(0)+1e-6
            Xt = (X[tr]-mu)/sd; Xv = (X[f]-mu)/sd
            Y = np.eye(8)[y[tr]]
            Wt = np.linalg.solve(Xt.T@Xt + lam*np.eye(d), Xt.T@(Y-Y.mean(0)))
            c += ((Xv@Wt).argmax(1)==y[f]).sum()
        accs.append(c/n)
    return round(np.mean(accs),4)
print('sum LN8+LN11', [cv_acc(LN(M[8])+LN(M[11]),y,l) for l in [100,200,400]])
print('cls12+mean8', [cv_acc(np.concatenate([Cl[12],M[8]],1),y,l) for l in [200,400,800]])
